#' Remove YAML frontmatter from content
#'
#' @param content Character vector of lines
#' @return Starting index for content after frontmatter (1 if no frontmatter)
extract_after_yaml <- function(content) {
  if (length(content) == 0 || content[1] != "---") {
    return(1)
  }

  yaml_end <- which(content == "---")
  if (length(yaml_end) < 2) {
    return(1)
  }

  yaml_end[2] + 1
