# Remove YAML frontmatter from text content
#
# Detects and strips YAML frontmatter (delimited by `---`) from the beginning
# of content, returning the starting index for the actual content.
#
# @param lines Character vector of lines to process
# @return Integer index where content begins (1 if no frontmatter)

remove_yaml_frontmatter <- function(lines) {
  if (length(lines) == 0 || lines[1] != "---") {
    return(1L)
  }

  yaml_end <- which(lines == "---")
  if (length(yaml_end) >= 2) {
    return(yaml_end[2] + 1L)
  }

  1L
}

