extract_text_after_yaml_frontmatter <- function(lines) {
  if (length(lines) == 0 || lines[1] != "---") {
    return(lines)
  }

  yaml_end <- which(lines == "---")
  if (length(yaml_end) < 2) {
    return(lines)
  }

  lines[(yaml_end[2] + 1):length(lines)]
}

